{
  "name": "数据维度选择控件",
  "name_en": "Dimension Selection Widget",
  "manufacturer": "",
  "description": "这不是可识别的实体实验仪器，而是一个实验数据可视化与流程图界面中的图形控件。它用于从数据集里选择维度、坐标轴或因变量，并可配合节点界面、快照视图和监视刷新间隔输入等组件，服务于实验数据浏览、绘图配置和交互式分析。",
  "description_en": "This is not an identifiable physical lab instrument but a GUI component used in laboratory data visualization and flowchart interfaces. It is used to select dimensions, axes, or dependent variables from datasets, and can work with node widgets, snapshot views, and monitor interval inputs for experimental data browsing, plot configuration, and interactive analysis.",
  "tag_hints": [
    "data dimension selection",
    "dataset visualization",
    "plot axis selection",
    "flowchart GUI",
    "interactive data analysis",
    "snapshot viewer",
    "monitor refresh interval"
  ],
  "actions": [
    {
      "action_name": "auto-connectNode",
      "description": "连接到数据处理节点，以便根据节点中的数据更新可选维度。",
      "description_en": "Connect to a data-processing node so the available dimensions can be updated from the node data."
    },
    {
      "action_name": "auto-setDimensions",
      "description": "设置可供选择的数据维度列表。",
      "description_en": "Set the list of data dimensions available for selection."
    },
    {
      "action_name": "auto-signalDimensionSelection",
      "description": "发出当前维度选择变化信号。",
      "description_en": "Emit a signal for the current dimension selection change."
    },
    {
      "action_name": "auto-spinValueChanged",
      "description": "发出或处理监视/刷新时间间隔的变化。",
      "description_en": "Emit or handle a change in the monitor/refresh interval."
    },
    {
      "action_name": "auto-setDefaultStyle",
      "description": "设置控件的默认显示样式。",
      "description_en": "Set the default display style of the widget."
    },
    {
      "action_name": "auto-addNodeWidget",
      "description": "向界面中添加一个节点控件。",
      "description_en": "Add a node widget to the interface."
    },
    {
      "action_name": "auto-addNodeWidgetsFromFlowchart",
      "description": "根据流程图向界面中添加节点控件。",
      "description_en": "Add node widgets to the interface based on a flowchart."
    },
    {
      "action_name": "auto-closeEvent",
      "description": "处理窗口或控件关闭事件。",
      "description_en": "Handle the window or widget close event."
    },
    {
      "action_name": "auto-loadSnapshot",
      "description": "加载数据快照或状态快照。",
      "description_en": "Load a data snapshot or state snapshot."
    },
    {
      "action_name": "auto-restart_widget",
      "description": "重启或重新初始化控件。",
      "description_en": "Restart or reinitialize the widget."
    },
    {
      "action_name": "auto-getSelected",
      "description": "获取当前选中的维度。",
      "description_en": "Get the currently selected dimension or dimensions."
    },
    {
      "action_name": "auto-setSelected",
      "description": "设置当前选中的维度。",
      "description_en": "Set the currently selected dimension or dimensions."
    },
    {
      "action_name": "auto-emitSelection",
      "description": "发出当前选择结果。",
      "description_en": "Emit the current selection."
    }
  ]
}

